style.css:
@-moz-document domain("classroom.google.com") {
/* Main Background */
    body, .zQTmif, .g3VIld, .JwQpJ {
        background-color: #e0f7ff !important;
    }

    /* Headers & Navigation */
    .YVvGBb, .oBSRLe, .aP4mo, .gb_vd, .gb_Wd {
        background-color: #b3e5fc !important;
        color: #006064 !important;
    }

    /* Cards & Containers */
    .gHz6xd, .ITp7Ee, .onkcG, .I3EnF, .zWGUib {
        background-color: #b3e5fc !important;
        color: #006064 !important;
    }

    /* Text Colors */
    .onkcG, .iymv3b, .zHQkBf {
        color: #006064 !important;
        background-color: transparent !important;
    }

    /* Buttons */
    .VfPpkd-LgbsSe, .VfPpkd-LgbsSe-OWXEXe-INsAgc, .VfPpkd-Bz112c-LgbsSe {
        background-color: #81d4fa !important;
        color: #fff !important;
        border-color: #4fc3f7 !important;
    }

    /* Dropdown Menus */
    .VfPpkd-StrnGf-rymPhb {
        background-color: #81d4fa !important;
        color: #006064 !important;
    }

    /* Hover Effects */
    .onkcG:hover, .iymv3b:hover, .VfPpkd-LgbsSe:hover, .VfPpkd-StrnGf-rymPhb:hover {
        background-color: #4fc3f7 !important;
    }

    /* Borders */
    .VfPpkd-StrnGf-rymPhb, .gHz6xd, .ITp7Ee, .JwQpJ {
        border-color: #4fc3f7 !important;
    }

    /* Disable Text Selection and Background Highlighting */
    * {
        user-select: none !important;
        background-color: transparent !important;
        outline: none !important;
    }
}
